+// Access: API keys with a role each, and the audit trail of requests that
+// change data (docs/DATA.md "Access"). Audit entries are never edited or
+// deleted.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed; each may do what the ones before it may. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record ({ key, name, role }) for `key`, or null when unknown. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const want = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), want) && !found) found = k;
+  }
+  return found;
+}
+
+/** True when `role` is a known role at least as strong as `required`. */
+export function allows(role, required) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(required);
+}
+
+/** Appends an audit entry and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
